Cc: Changwei Ge <gechangwei@live.cn>
Cc: Jun Piao <piaojun@huawei.com>
Cc: Heming Zhao <heming.zhao@suse.com>
Signed-off-by: Andrew Morton <akpm@linux-foundation.org>

Here is the root cause:
The bug is caused by calling `ocfs2_set_new_buffer_uptodate()` on a user-controlled group block before validating it via `ocfs2_verify_group_and_input()`, and using the wrong inode cache (`INODE_CACHE(inode)` instead of `INODE_CACHE(main_bm_inode)`). This premature caching can lead to a BUG_ON assertion failure when the block is invalid, and the incorrect cache context causes inconsistency with later journal operations.

Here is the patch:
 /* Add a new group descriptor to global_bitmap. */
 int ocfs2_group_add(struct inode *inode, struct ocfs2_new_group_input *input)
 {
 	int ret;
 	handle_t *handle;
 	struct buffer_head *main_bm_bh = NULL;
 	struct inode *main_bm_inode = NULL;
 	struct ocfs2_dinode *fe = NULL;
 	struct ocfs2_super *osb = OCFS2_SB(inode->i_sb);
 	struct buffer_head *group_bh = NULL;
 	struct ocfs2_group_desc *group = NULL;
 	struct ocfs2_chain_list *cl;
 	struct ocfs2_chain_rec *cr;
 	u16 cl_bpc;
 	u64 bg_ptr;

 	if (unlikely(ocfs2_emergency_state(osb)))
 		return -EROFS;

 	main_bm_inode = ocfs2_get_system_file_inode(osb,
 						    GLOBAL_BITMAP_SYSTEM_INODE,
 						    OCFS2_INVALID_SLOT);
 	if (!main_bm_inode) {
 		ret = -EINVAL;
 		mlog_errno(ret);
 		goto out;
 	}

 	inode_lock(main_bm_inode);

 	ret = ocfs2_inode_lock(main_bm_inode, &main_bm_bh, 1);
 	if (ret < 0) {
 		mlog_errno(ret);
 		goto out_mutex;
 	}

 	fe = (struct ocfs2_dinode *)main_bm_bh->b_data;

 	if (le16_to_cpu(fe->id2.i_chain.cl_cpg) !=
 		ocfs2_group_bitmap_size(osb->sb, 0,
 					osb->s_feature_incompat) * 8) {
 		mlog(ML_ERROR, "The disk is too old and small."
 		     " Force to do offline resize.");
 		ret = -EINVAL;
 		goto out_unlock;
 	}

 	ret = ocfs2_read_blocks_sync(osb, input->group, 1, &group_bh);
 	if (ret < 0) {
 		mlog(ML_ERROR, "Can't read the group descriptor # %llu "
 		     "from the device.", (unsigned long long)input->group);
 		goto out_unlock;
 	}

-	ocfs2_set_new_buffer_uptodate(INODE_CACHE(inode), group_bh);
-
 	ret = ocfs2_verify_group_and_input(main_bm_inode, fe, input, group_bh);
 	if (ret) {
 		mlog_errno(ret);
 		goto out_free_group_bh;
 	}

+	ocfs2_set_new_buffer_uptodate(INODE_CACHE(main_bm_inode), group_bh);
+
 	trace_ocfs2_group_add((unsigned long long)input->group,
 			       input->chain, input->clusters, input->frees);

 	handle = ocfs2_start_trans(osb, OCFS2_GROUP_ADD_CREDITS);
 	if (IS_ERR(handle)) {
 		mlog_errno(PTR_ERR(handle));
 		ret = -EINVAL;
-		goto out_free_group_bh;
+		goto out_remove_cache;
 	}

 	cl_bpc = le16_to_cpu(fe->id2.i_chain.cl_bpc);
 	cl = &fe->id2.i_chain;
 	cr = &cl->cl_recs[input->chain];

 	ret = ocfs2_journal_access_gd(handle, INODE_CACHE(main_bm_inode),
 				      group_bh, OCFS2_JOURNAL_ACCESS_WRITE);
 	if (ret < 0) {
 		mlog_errno(ret);
 		goto out_commit;
 	}

 	group = (struct ocfs2_group_desc *)group_bh->b_data;
 	bg_ptr = le64_to_cpu(group->bg_next_group);
 	group->bg_next_group = cr->c_blkno;
 	ocfs2_journal_dirty(handle, group_bh);

 	ret = ocfs2_journal_access_di(handle, INODE_CACHE(main_bm_inode),
 				      main_bm_bh, OCFS2_JOURNAL_ACCESS_WRITE);
 	if (ret < 0) {
 		group->bg_next_group = cpu_to_le64(bg_ptr);
 		mlog_errno(ret);
 		goto out_commit;
 	}

 	if (input->chain == le16_to_cpu(cl->cl_next_free_rec)) {
 		le16_add_cpu(&cl->cl_next_free_rec, 1);
 		memset(cr, 0, sizeof(struct ocfs2_chain_rec));
 	}

 	cr->c_blkno = cpu_to_le64(input->group);
 	le32_add_cpu(&cr->c_total, input->clusters * cl_bpc);
 	le32_add_cpu(&cr->c_free, input->frees * cl_bpc);

 	le32_add_cpu(&fe->id1.bitmap1.i_total, input->clusters *cl_bpc);
 	le32_add_cpu(&fe->id1.bitmap1.i_used,
 		     (input->clusters - input->frees) * cl_bpc);
 	le32_add_cpu(&fe->i_clusters, input->clusters);

 	ocfs2_journal_dirty(handle, main_bm_bh);

 	spin_lock(&OCFS2_I(main_bm_inode)->ip_lock);
 	OCFS2_I(main_bm_inode)->ip_clusters = le32_to_cpu(fe->i_clusters);
 	le64_add_cpu(&fe->i_size, (u64)input->clusters << osb->s_clustersize_bits);
 	spin_unlock(&OCFS2_I(main_bm_inode)->ip_lock);
 	i_size_write(main_bm_inode, le64_to_cpu(fe->i_size));

 	ocfs2_update_super_and_backups(main_bm_inode, input->clusters);

 out_commit:
 	ocfs2_commit_trans(osb, handle);

-out_free_group_bh:
+out_remove_cache:
 	if (ret < 0)
-		ocfs2_remove_from_cache(INODE_CACHE(inode), group_bh);
+		ocfs2_remove_from_cache(INODE_CACHE(main_bm_inode), group_bh);
+
+out_free_group_bh:
 	brelse(group_bh);

 out_unlock:
 	brelse(main_bm_bh);

 	ocfs2_inode_unlock(main_bm_inode, 1);

 out_mutex:
 	inode_unlock(main_bm_inode);
 	iput(main_bm_inode);

 out:
 	return ret;
 }
